/**
 * A ecolocalização — porte de `componentes/viz/eco.js`.
 *
 * O golfinho emite um clique, o som viaja na água, bate na presa e volta. Do
 * TEMPO desse ida e volta sai a distância: velocidade do som × tempo ÷ 2. O ÷ 2
 * é o que trava as pessoas — o som andou o caminho duas vezes, e é por isso que
 * a conta divide.
 *
 * A cena põe a estimativa como uma linha que se move sobre a água: quando ela
 * encosta na presa, o eco volta e o animal "vê" no escuro.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const eco: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const estimativa = Math.max(0, numeroDe(valores, 'd', 0));
    const alvo = numeroDe(info, 'alvo', 65);
    const ok = info.ok === true;

    titulo(ctx, L, A, 'Enxergar com o ouvido');

    const margem = L * 0.12;
    const faixa = L * 0.76;
    const golfinhoX = margem;
    const y = A * 0.52;
    const presaX = margem + (alvo / 100) * faixa;
    const focoX = margem + (estimativa / 100) * faixa;

    // A água.
    const agua = ctx.createLinearGradient(0, A * 0.2, 0, A);
    agua.addColorStop(0, 'rgb(60 74 158 / 12%)');
    agua.addColorStop(1, 'rgb(60 74 158 / 26%)');
    ctx.fillStyle = agua;
    ctx.fillRect(0, A * 0.2, L, A * 0.75);

    // O clique indo: arcos que crescem a partir do animal.
    ctx.strokeStyle = cor.azul;
    ctx.lineWidth = 1.8;
    for (let i = 0; i < 3; i++) {
      const fase = (t * 0.35 + i / 3) % 1;
      ctx.globalAlpha = 0.6 * (1 - fase);
      ctx.beginPath();
      ctx.arc(golfinhoX, y, fase * faixa, -0.6, 0.6);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    // O eco voltando: só existe quando a presa foi de fato alcançada.
    if (ok) {
      ctx.strokeStyle = cor.verde;
      ctx.lineWidth = 2;
      for (let i = 0; i < 2; i++) {
        const fase = (t * 0.5 + i / 2) % 1;
        ctx.globalAlpha = 0.7 * (1 - fase);
        ctx.beginPath();
        ctx.arc(presaX, y, fase * (presaX - golfinhoX), Math.PI - 0.6, Math.PI + 0.6);
        ctx.stroke();
      }
      ctx.globalAlpha = 1;
    }

    // O golfinho.
    ctx.fillStyle = cor.fraco;
    ctx.beginPath();
    ctx.ellipse(golfinhoX, y, 24, 13, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(golfinhoX - 22, y);
    ctx.lineTo(golfinhoX - 36, y - 10);
    ctx.lineTo(golfinhoX - 36, y + 10);
    ctx.closePath();
    ctx.fill();

    // A estimativa, como uma sonda que varre a água.
    ctx.strokeStyle = ok ? cor.verde : cor.texto;
    ctx.setLineDash([4, 4]);
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(focoX, A * 0.24);
    ctx.lineTo(focoX, A * 0.82);
    ctx.stroke();
    ctx.setLineDash([]);

    // A presa: acende quando é encontrada.
    ctx.fillStyle = ok ? cor.verde : cor.trilho;
    ctx.beginPath();
    ctx.ellipse(presaX, y, 11, 6.5, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(presaX + 10, y);
    ctx.lineTo(presaX + 19, y - 6);
    ctx.lineTo(presaX + 19, y + 6);
    ctx.closePath();
    ctx.fill();

    texto(
      ctx,
      `eco ≈ ${Math.round(numeroDe(info, 'tEco', 0))} ms`,
      golfinhoX + 12,
      y - 30,
      limitar(A * 0.04, 9, 13),
      { cor: cor.fraco, peso: 700, alinhamento: 'left' },
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      'Presa localizada pelo eco ✔',
      'Ajuste a distância até a sonda tocar a presa.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default eco;
